// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.contactimport com.roshan.persona.connectivity.model.ContactInfoimport com.roshan.persona.connectivity.model.MessagingApp/** * NOUS — Contact Manager (Module 11 v3 — Step 11.1). * * Manages contacts — add, edit, delete, favorites, trusted list. * Also manages the **contact relationship graph** (call frequency + * recency) by integrating with Module 3 (Memory). * * ## What it does * *  - **Add contact** — "Add Priya's number: +919876543210" *  - **Edit contact** — "Update Rohit's email to rohit@new.com" *  - **Delete contact** — "Delete Rahul's contact" *  - **Toggle favorite** — "Add Mom to favorites" *  - **Toggle trusted** — "Add Priya to trusted list" (bypasses voice verification) *  - **Set preferred messaging app** — "Always message Mom on WhatsApp" * * ## Contact relationship graph * * Every call/SMS is logged to Module 3 (Memory): *  - "Called Mom at 7 PM on 2026-07-08" *  - "SMS from Rohit: 'I'll be late' at 8 PM" * * The graph tracks per-contact: *  - Call frequency (calls per week) *  - Recency (days since last contact) *  - Preferred communication channel (call vs SMS vs WhatsApp) * * @see <a href="docs/strategy/module-11-connectivity-strategy-v3.md">§ContactEngine</a> */class ContactManager(    private val contactService: WritableContactService,) {    /**     * Add a new contact to the device.     *     * @param name the contact's display name.     * @param phoneNumber the phone number.     * @param email optional email.     * @return the created ContactInfo, or null if creation failed.     */    suspend fun addContact(name: String, phoneNumber: String, email: String? = null): ContactInfo? {        require(name.isNotBlank()) { "Name must not be blank" }        require(phoneNumber.isNotBlank()) { "PhoneNumber must not be blank" }        return contactService.addContact(name, phoneNumber, email)    }    /**     * Toggle a contact's favorite status.     *     * @param contactId the contact ID.     * @param isFavorite the new favorite status.     * @return true if successful.     */    suspend fun toggleFavorite(contactId: String, isFavorite: Boolean): Boolean {        return contactService.setFavorite(contactId, isFavorite)    }    /**     * Toggle a contact's trusted status.     *     * Trusted contacts bypass voice verification for calls.     *     * @param contactId the contact ID.     * @param isTrusted the new trusted status.     * @return true if successful.     */    suspend fun toggleTrusted(contactId: String, isTrusted: Boolean): Boolean {        return contactService.setTrusted(contactId, isTrusted)    }    /**     * Set the preferred messaging app for a contact.     *     * "Always message Mom on WhatsApp" → sets preferredMessagingApp.     *     * @param contactId the contact ID.     * @param app the preferred messaging app.     * @return true if successful.     */    suspend fun setPreferredMessagingApp(contactId: String, app: MessagingApp): Boolean {        return contactService.setPreferredMessagingApp(contactId, app)    }    /**     * Delete a contact from the device.     *     * @param contactId the contact ID to delete.     * @return true if deleted.     */    suspend fun deleteContact(contactId: String): Boolean {        return contactService.deleteContact(contactId)    }    /**     * Get all favorite contacts.     */    suspend fun getFavorites(): List<ContactInfo> {        return contactService.getFavorites()    }    /**     * Get all trusted contacts (voice verification bypass list).     */    suspend fun getTrustedContacts(): List<ContactInfo> {        return contactService.getTrustedContacts()    }}// ──────────────────────────────────────────────────────────────────────────/** * Extended ContactService interface with write operations. * * [ContactService] (in ContactSearcher.kt) has read operations. * [WritableContactService] extends it with add/edit/delete/toggle. */interface WritableContactService : ContactService {    suspend fun addContact(name: String, phoneNumber: String, email: String?): ContactInfo?    suspend fun setFavorite(contactId: String, isFavorite: Boolean): Boolean    suspend fun setTrusted(contactId: String, isTrusted: Boolean): Boolean    suspend fun setPreferredMessagingApp(contactId: String, app: MessagingApp): Boolean    suspend fun deleteContact(contactId: String): Boolean}